INSERT INTO public.words (topic_id, word, phonetic, pos, meaning, example_sentence, lesson_name, lesson_order, word_order)
VALUES
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cursory', '/ˈkɜːrsəri/', 'adj.', 'Nhanh, lướt qua, không kỹ lưỡng', 'A cursory inspection of the archival manuscripts failed to reveal the subtle marginalia that later proved crucial to deciphering the author''s true intent.', 'Lesson 8', 8, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'curtail', '/kɜːrˈteɪl/', 'v.', 'Cắt bớt, rút ngắn, hạn chế', 'In response to mounting inflationary pressures and widening budget deficits, the ministry was forced to curtail public expenditures on infrastructure.', 'Lesson 8', 8, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cynical', '/ˈsɪnɪkl/', 'adj.', 'Hoài nghi, cay độc, thiếu tin tưởng vào lòng tốt', 'Hardened by decades of political corruption and broken campaign promises, the electorate adopted an increasingly cynical view of government reform initiatives.', 'Lesson 8', 8, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cynosure', '/ˈsaɪnəʃʊr/', 'n.', 'Trung tâm của sự chú ý, tâm điểm ngưỡng mộ', 'With its soaring cantilevered arches and iridescent glass facade, the newly inaugurated concert hall quickly became the architectural cynosure of the entire metropolis.', 'Lesson 8', 8, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dabble', '/ˈdæbl/', 'v.', 'Học đòi, tham gia một cách tài tử, không chuyên sâu', 'Although the Renaissance polymath chose to dabble in alchemy and astrology during his youth, his lasting intellectual legacy rested upon rigorous empirical mathematics.', 'Lesson 8', 8, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dais', '/ˈdeɪɪs/', 'n.', 'Bục danh dự, bục phát biểu', 'Ascending the velvet-draped dais at the front of the council chamber, the chancellor prepared to deliver his annual address to the assembled foreign dignitaries.', 'Lesson 8', 8, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dank', '/dæŋk/', 'adj.', 'Ẩm thấp, lạnh lẽo và khó chịu', 'Deep within the medieval fortress''s subterranean vaults, centuries of archival parchment were slowly degraded by the dank, unventilated air.', 'Lesson 8', 8, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dapper', '/ˈdæpər/', 'adj.', 'Gọn gàng, bảnh bao, tươm tất', 'Attired in a bespoke three-piece tweed suit and polished leather brogues, the dapper literary critic commanded immediate respect upon entering the lecture hall.', 'Lesson 8', 8, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dappled', '/ˈdæpld/', 'adj.', 'Lốm đốm, loang lổ bóng râm và ánh sáng', 'Midday sunlight filtering through the dense canopy of ancient oaks cast a dappled pattern of gold and deep shadow across the forest path.', 'Lesson 8', 8, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'daub', '/dɔːb/', 'v.', 'Phết, trét, bôi cẩu thả', 'Rejecting classical smoothing techniques, the neo-expressionist painter used a wooden spatula to daub thick impasto swathes of crimson across the canvas.', 'Lesson 8', 8, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'daunt', '/dɔːnt/', 'v.', 'Làm nản lòng, làm thoái chí', 'Neither the vast expanse of the frozen polar tundra nor the perilous threat of blizzards could daunt the resolute polar explorers.', 'Lesson 8', 8, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dauntless', '/ˈdɔːntləs/', 'adj.', 'Dũng cảm, kiên cường, bất khuất', 'Celebrated in maritime lore, the dauntless captain steered his battered frigate straight through the hurricane to rescue the stranded whaling fleet.', 'Lesson 8', 8, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dawdle', '/ˈdɔːdl/', 'v.', 'Nhởn nhơ, lãng phí thời gian, chậm chạp', 'With the tide rising swiftly toward the cliff base, the marine surveyors could not dawdle while gathering intertidal specimen samples.', 'Lesson 8', 8, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deadlock', '/ˈdedlɑːk/', 'n.', 'Sự đình trệ, tình trạng bế tắc hoàn toàn', 'Bipartisan congressional negotiations reached an intractable deadlock when both committees refused to concede on key statutory spending caps.', 'Lesson 8', 8, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deadpan', '/ˈdedpæn/', 'adj.', 'Thản nhiên, tỉnh bơ, không biểu cảm', 'Delivering devastating satirical commentary with a completely deadpan demeanor, the essayist maintained an unsmiling gravity that amplified the humor.', 'Lesson 8', 8, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dearth', '/dɜːrθ/', 'n.', 'Sự khan hiếm, tình trạng thiếu thốn', 'An acute dearth of dependable documentary records from the early medieval kingdom forces contemporary historians to rely heavily on archaeological fragments.', 'Lesson 8', 8, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debacle', '/deɪˈbɑːkl/', 'n.', 'Thất bại thảm hại, sự sụp đổ hoàn toàn', 'Plagued by critical software errors and unprecedented cost overruns, the highly publicized satellite deployment unravelled into an embarrassing public relations debacle.', 'Lesson 8', 8, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debase', '/dɪˈbeɪs/', 'v.', 'Làm giảm giá trị, làm suy đồi phẩm chất', 'To finance prolonged foreign conflicts, the Roman emperor ordered the imperial mint to debase silver denarii with inferior alloys of copper and tin.', 'Lesson 8', 8, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debauch', '/dɪˈbɔːtʃ/', 'v.', 'Làm đồi bại, sa đọa, làm hư hỏng', 'Exploiting the young nobleman''s sudden inheritance, unprincipled courtiers conspired to debauch his senses with illicit gambling and lavish revelry.', 'Lesson 8', 8, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debilitate', '/dɪˈbɪlɪteɪt/', 'v.', 'Làm suy nhược, làm kiệt quệ', 'A protracted drought threatened to debilitate the agrarian regional economy, exhausting groundwater reservoirs and stunting seasonal crop yields.', 'Lesson 8', 8, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debonair', '/ˌdebəˈner/', 'adj.', 'Lịch lãm, hào hoa, phong nhã', 'Possessing an easy elegance and quick cosmopolitan wit, the debonair ambassador put rival emissaries at ease during the contentious peace summit.', 'Lesson 8', 8, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debris', '/dəˈbriː/', 'n.', 'Mảnh vỡ, đống đổ nát, tàn tích', 'Following the seismic shockwave, geological teams carefully examined the volcanic debris strewn across the caldera to reconstruct the eruption sequence.', 'Lesson 8', 8, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debunk', '/ˌdiːˈbʌŋk/', 'v.', 'Vạch trần, bóc trần sự sai lệch', 'Through methodical spectroscopic analysis, the astrophysicist managed to debunk the sensational hypothesis that celestial signals originated from intelligent alien life.', 'Lesson 8', 8, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debutante', '/ˈdebjuːtɑːnt/', 'n.', 'Thiếu nữ quý tộc lần đầu ra mắt giới thượng lưu', 'In Edwardian London, an aristocratic debutante was expected to observe strict rules of etiquette upon her presentation at the royal court.', 'Lesson 8', 8, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decadence', '/ˈdekədəns/', 'n.', 'Sự suy đồi, tình trạng sa đọa đạo đức hoặc văn hóa', 'Moral philosophers argued that the unchecked decadence of the gilded elite inevitably blinded them to the simmering grievances of the working class.', 'Lesson 8', 8, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decapitate', '/dɪˈkæpɪteɪt/', 'v.', 'Chặt đầu, xử trảm', 'During the zenith of the French Revolution, the radical Jacobin regime voted to decapitate King Louis XVI upon the scaffold in the Place de la Révolution.', 'Lesson 8', 8, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decelerate', '/ˌdiːˈseləreɪt/', 'v.', 'Giảm tốc độ, đi chậm lại', 'As monetary policymakers tightened credit to curb speculative bubbles, industrial investment and wage growth began to decelerate precipitously.', 'Lesson 8', 8, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deciduous', '/dɪˈsɪdʒuəs/', 'adj.', 'Rụng lá hằng năm, sớm rụng', 'Unlike the evergreen conifers dominating boreal landscapes, deciduous broadleaf trees enter winter dormancy by shedding their foliage to minimize moisture loss.', 'Lesson 8', 8, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decimate', '/ˈdesɪmeɪt/', 'v.', 'Tàn phá nặng nề, tiêu diệt số lượng lớn', 'The arrival of European pathogens such as smallpox proceeded to decimate indigenous populations who possessed no acquired immunological resistance.', 'Lesson 8', 8, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'detergent', '/dɪˈtɜːrdʒənt/', 'n.', 'Chất tẩy rửa', 'Environmental chemists demonstrated that phosphorus-rich synthetic detergent runoff accelerates harmful algal blooms that deplete dissolved oxygen in aquatic habitats.', 'Lesson 8', 8, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decipher', '/dɪˈsaɪfər/', 'v.', 'Giải mã, làm sáng tỏ điều phức tạp', 'Working in seclusion at Bletchley Park, cryptanalysts designed early electromechanical computing devices to decipher encrypted Enigma military communications.', 'Lesson 8', 8, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'declivity', '/dɪˈklɪvəti/', 'n.', 'Dốc thoai thoải xuống, sườn dốc xuống', 'Heavy seasonal rains saturated the steep declivity above the mountain hamlet, causing dislodged boulders and mud to cascade down the hillside.', 'Lesson 8', 8, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decollete', '/ˌdeɪkɑːlˈteɪ/', 'adj.', 'Khoét sâu cổ áo', 'The portrait sparked aristocratic controversy for depicting the young marchioness in a daringly decollete velvet evening bodice.', 'Lesson 8', 8, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decomposition', '/ˌdiːˌkɑːmpəˈzɪʃn/', 'n.', 'Sự phân hủy, quá trình phân rã', 'Forest saprophytes play an indispensable ecological role by driving the decomposition of fallen timber into bioavailable soil nutrients.', 'Lesson 8', 8, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decorum', '/dɪˈkɔːrəm/', 'n.', 'Sự đúng mực, phép lịch sự, phong thái đoan trang', 'Even when enduring aggressive questioning during senate hearings, the judicial nominee preserved impeccable decorum and spoke in measured, respectful tones.', 'Lesson 8', 8, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decoy', '/ˈdiːkɔɪ/', 'n.', 'Mồi nhử, vật nghi binh đánh lạc hướng', 'Allied commanders positioned dummy inflatable tanks along the coastline to serve as an elaborate decoy, deceiving axis reconnaissance regarding the true invasion site.', 'Lesson 8', 8, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decrepit', '/dɪˈkrepɪt/', 'adj.', 'Già yếu, rệu rã, mục nát', 'The rural community struggled to preserve its decrepit timber covered bridge after decades of weathering and structural rot weakened its floor joists.', 'Lesson 8', 8, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decrepitude', '/dɪˈkrepɪtuːd/', 'n.', 'Tình trạng già yếu, sự rệu rã, tình trạng đổ nát', 'Once a resplendent symbol of imperial prestige, the abandoned palace succumbed to architectural decrepitude as weeds cracked its marble terraces.', 'Lesson 8', 8, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decry', '/dɪˈkraɪ/', 'v.', 'Công khai chỉ trích, lên án', 'Humanitarian observers stepped forward to decry the arbitrary detention of peaceful demonstrators as an egregious violation of basic civil liberties.', 'Lesson 8', 8, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deducible', '/dɪˈduːsəbl/', 'adj.', 'Có thể suy luận được từ thông tin sẵn có', 'From the periodic dimming of the star''s stellar luminosity, the presence of an orbiting gas giant was readily deducible without direct telescopic imaging.', 'Lesson 8', 8, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deface', '/dɪˈfeɪs/', 'v.', 'Làm hư hại bề mặt, bôi bẩn làm mất mỹ quan', 'Outraged citizens condemned the vandals who conspired to deface the bronze war memorial with crude markings overnight.', 'Lesson 8', 8, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defame', '/dɪˈfeɪm/', 'v.', 'Phỉ báng, bôi nhọ thanh danh', 'In his opening statement, the barrister argued that sensationalist tabloids printed falsehoods specifically designed to defame the prime minister''s personal integrity.', 'Lesson 8', 8, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'default', '/dɪˈfɔːlt/', 'n.', 'Sự vỡ nợ, sự không thực hiện được nghĩa vụ', 'Fearing sovereign default on national sovereign bonds, credit rating agencies downgraded the country''s debt to junk status.', 'Lesson 8', 8, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defeatist', '/dɪˈfiːtɪst/', 'adj.', 'Bi quan, có tư tưởng chủ bại', 'The prime minister urged the wartime cabinet to banish all defeatist rhetoric and focus instead on mobilizing industrial capacity for national defense.', 'Lesson 8', 8, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defection', '/dɪˈfekʃn/', 'n.', 'Sự đào ngũ, sự phản bội đào tẩu', 'The sudden defection of the chief nuclear scientist dealt a catastrophic blow to the regime''s clandestine weapons development program.', 'Lesson 8', 8, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defer', '/dɪˈfɜːr/', 'v.', 'Trì hoãn, hoãn lại', 'Confronted by inconclusive clinical trial results, the regulatory panel voted to defer final approval of the therapeutic compound until further data emerged.', 'Lesson 8', 8, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deference', '/ˈdefərəns/', 'n.', 'Sự tôn kính, sự chiều theo ý kiến người khác vì nể trọng', 'Showing great deference to constitutional precedent, the appellate judges refrained from overturning the longstanding common-law doctrine.', 'Lesson 8', 8, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defiance', '/dɪˈfaɪəns/', 'n.', 'Sự thách thức, thái độ bất tuân công khai', 'Standing resolutely before an unyielding military cordon, the factory strikers raised their banners in collective defiance of the martial decree.', 'Lesson 8', 8, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defile', '/dɪˈfaɪl/', 'v.', 'Làm ô uế, báng bổ sự thanh khiết', 'Environmental advocates filed a federal suit against the chemical manufacturer for permitting toxic industrial effluent to defile the pristine river basin.', 'Lesson 8', 8, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'definitive', '/dɪˈfɪnətɪv/', 'adj.', 'Dứt khoát, mang tính quyết định, có thẩm quyền tối hậu', 'Scholars universally regarded the professor''s monumental archival study as the definitive historical treatment of the diplomatic crisis of 1914.', 'Lesson 8', 8, 100),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deflect', '/dɪˈflekt/', 'v.', 'Làm lệch hướng, chuyển hướng', 'Rather than addressing the auditor''s pointed inquiries regarding the misallocated funds, the spokesperson attempted to deflect scrutiny by questioning the committee''s political impartiality.', 'Lesson 9', 9, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defoliate', '/diːˈfoʊ.li.eɪt/', 'v.', 'Làm rụng lá, làm trơ cành', 'During the prolonged counterinsurgency campaign, military strategists authorized chemical spraying to defoliate dense jungle canopies and strip enemy fighters of natural concealment.', 'Lesson 9', 9, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defray', '/dɪˈfreɪ/', 'v.', 'Thanh toán, chi trả (chi phí)', 'The civic endowment was established specifically to defray tuition expenses and laboratory fees for promising underprivileged scholars pursuing doctoral research.', 'Lesson 9', 9, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deft', '/deft/', 'adj.', 'Khéo léo, nhanh nhẹn, tinh tế', 'Through deft diplomatic maneuvering and subtle textual compromises, the veteran envoy negotiated a landmark ceasefire without surrendering sovereign territory.', 'Lesson 9', 9, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defunct', '/dɪˈfʌŋkt/', 'adj.', 'Không còn tồn tại, ngừng hoạt động', 'Archival researchers examined surviving ledgers from the defunct trading guild, reconstructing how catastrophic banking panics caused its sudden dissolution in 1873.', 'Lesson 9', 9, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defuse', '/diːˈfjuːz/', 'v.', 'Tháo ngòi nổ, xoa dịu căng thẳng', 'The foreign minister convened emergency bilateral talks in Geneva to defuse mounting cross-border hostility before military mobilizations escalated into open warfare.', 'Lesson 9', 9, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'degenerate', '/dɪˈdʒen.ə.reɪt/', 'v.', 'Thoái hóa, suy đồi, biến chất', 'In his critique of republican governance, the philosopher warned that unchecked factional polarization would inevitably cause democratic deliberations to degenerate into mob rule.', 'Lesson 9', 9, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'degradation', '/ˌdeɡ.rəˈdeɪ.ʃən/', 'n.', 'Sự suy thoái, sự xuống cấp', 'Marine biologists attributed the rapid ecological degradation of coral barrier reefs to rising sea temperatures, agricultural runoff, and coastal industrialization.', 'Lesson 9', 9, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dehydrate', '/diːˈhaɪ.dreɪt/', 'v.', 'Làm mất nước, làm khô cạn', 'Prolonged exposure to the scorching desert winds threatened to dehydrate the stranded geological survey team, compelling them to ration their dwindling water supplies with extreme parsimony.', 'Lesson 9', 9, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deify', '/ˈdiː.ɪ.faɪ/', 'v.', 'Tôn sùng như thần, thần thánh hóa', 'Seeking to legitimize autocratic authority and command unquestioning obedience, ancient imperial dynasties routinely orchestrated religious rituals to deify deceased sovereigns.', 'Lesson 9', 9, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deign', '/deɪn/', 'v.', 'Hạ mình, chiếu cố làm điều gì', 'Convinced of his patrician lineage and aesthetic superiority, the reclusive composer would not deign to respond to critical reviews penned by municipal journalists.', 'Lesson 9', 9, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delectable', '/dɪˈlek.tə.bəl/', 'adj.', 'Ngon lành, thú vị, hấp dẫn', 'Attendants at the renaissance feast marvelled at the delectable pastries infused with saffron and almond paste, which were presented on ornate silver platters beneath candlelit vaults.', 'Lesson 9', 9, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delete', '/dɪˈliːt/', 'v.', 'Xóa bỏ, gạch bỏ', 'Before releasing the historical transcripts to the public, the intelligence review board was legally required to delete redacted paragraphs containing classified operative identities.', 'Lesson 9', 9, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deleterious', '/ˌdel.əˈtɪr.i.əs/', 'adj.', 'Có hại, độc hại, gây tổn hại', 'Longitudinal epidemiological studies established that chronic sleep fragmentation exerts deleterious effects on cardiovascular health and executive cognitive functioning.', 'Lesson 9', 9, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deliberate', '/dɪˈlɪb.ər.ət/', 'adj.', 'Có tính toán, thận trọng, cố ý', 'The constitutional framers instituted overlapping bicameral review as a deliberate mechanism to slow legislative passage and guard against impulsive popular passions.', 'Lesson 9', 9, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delineate', '/dɪˈlɪn.i.eɪt/', 'v.', 'Phác họa, mô tả chi tiết, phân định rõ', 'The boundary treaty signed in Paris sought to delineate disputed territorial borders along natural alpine ridges, eliminating jurisdictional ambiguities between neighboring states.', 'Lesson 9', 9, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delirium', '/dɪˈlɪr.i.əm/', 'n.', 'Sự mê sảng, trạng thái cuồng loạn', 'Plagued by virulent septic fever, the wounded soldier lapsed into a state of restless delirium, hallucinating phantom voices and reliving artillery barrages.', 'Lesson 9', 9, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delude', '/dɪˈluːd/', 'v.', 'Lừa dối, đánh lừa, làm cho lầm tưởng', 'Authoritarian regimes frequently employ fabricated economic statistics to delude the citizenry into believing that national production remains robust amid catastrophic shortages.', 'Lesson 9', 9, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deluge', '/ˈdel.juːdʒ/', 'n.', 'Trận đại hồng thủy, sự tràn ngập dồn dập', 'When torrential monsoon storms shattered the earthen reservoir walls, an unstoppable deluge inundated downstream farming communities and wrecked regional transportation infrastructure.', 'Lesson 9', 9, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delusion', '/dɪˈluː.ʒən/', 'n.', 'Ảo tưởng, niềm tin sai lầm', 'Blind to impending fiscal bankruptcy, the company''s executive board clung to the stubborn delusion that consumer demand for obsolete technology would miraculously rebound.', 'Lesson 9', 9, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delve', '/delv/', 'v.', 'Đào sâu, nghiên cứu kỹ lưỡng', 'To resolve the longstanding anthropological enigma, the research team had to delve into centuries of church baptismal registries and colonial census rolls.', 'Lesson 9', 9, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demagogue', '/ˈdem.ə.ɡɑːɡ/', 'n.', 'Kẻ mị dân, nhà chính trị kích động quần chúng', 'Historians observed that the populist demagogue rose to power by scapegoating ethnic minorities and exploiting widespread economic distress with incendiary rhetoric.', 'Lesson 9', 9, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demean', '/dɪˈmiːn/', 'v.', 'Hạ thấp phẩm giá, làm nhục', 'Advocates for penal reform argued that subjecting incarcerated individuals to degrading public humiliation served only to demean their human spirit without deterring future crime.', 'Lesson 9', 9, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demeanor', '/dɪˈmiː.nər/', 'n.', 'Cử chỉ, thái độ, phong thái', 'Despite hostile interruptions from opposition lawmakers, the prime minister maintained a remarkably composed demeanor, answering contentious allegations with measured cadence.', 'Lesson 9', 9, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demented', '/dɪˈmen.tɪd/', 'adj.', 'Loạn trí, điên cuồng, mất trí', 'Cut off from communication in the arctic wasteland, the stranded expedition commander succumbed to demented suspicions, imagining insubordination among his most dutiful officers.', 'Lesson 9', 9, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demise', '/dɪˈmaɪz/', 'n.', 'Cái chết, sự sụp đổ, sự lụi tàn', 'Archaeological excavations confirmed that abrupt megadroughts and resource overexploitation precipitated the sudden demise of the once-flourishing Bronze Age civilization.', 'Lesson 9', 9, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demolition', '/ˌdem.əˈlɪʃ.ən/', 'n.', 'Sự phá hủy, sự đánh sập', 'Civic heritage coalitions mobilized intense public opposition against the planned demolition of the historic Beaux-Arts opera house in favor of a commercial parking garage.', 'Lesson 9', 9, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demoniac', '/dɪˈmoʊ.ni.æk/', 'adj.', 'Ma quỷ, cuồng loạn, quỷ ám', 'In Mary Shelley''s gothic narrative, Victor Frankenstein beheld his monstrous creation with horror, recoiling from the creature''s demoniac grimace and unnatural physical stature.', 'Lesson 9', 9, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demur', '/dɪˈmɜːr/', 'v.', 'Phản đối, ngần ngại, do dự', 'Although the cabinet advocated immediate martial law, the chief justice did not hesitate to demur, insisting that constitutional safeguards could not be suspended during peacetime.', 'Lesson 9', 9, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demure', '/dɪˈmjʊr/', 'adj.', 'Kín đáo, e dè, thùy mị', 'Behind her modest attire and demure bearing lay an astute political mind that deftly orchestrated backchannel negotiations between hostile factional leaders.', 'Lesson 9', 9, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demystify', '/diːˈmɪs.tɪ.faɪ/', 'v.', 'Làm sáng tỏ, làm rõ (điều phức tạp)', 'The documentary series aimed to demystify complex macroeconomic monetary policies, translating abstruse econometric modeling into lucid visual concepts for ordinary citizens.', 'Lesson 9', 9, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'denigrate', '/ˈden.ɪ.ɡreɪt/', 'v.', 'Gièm pha, bôi nhọ, hạ thấp phẩm giá', 'Rather than evaluating the merits of the breakthrough cosmological hypothesis, established academics unfairly sought to denigrate the young astronomer''s empirical methodology.', 'Lesson 9', 9, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'denizen', '/ˈden.ɪ.zən/', 'n.', 'Cư dân, động thực vật bản địa', 'Adapted to survive in perpetual darkness beneath extreme hydrostatic pressure, the viperfish reigns as a formidable denizen of the oceanic bathypelagic zone.', 'Lesson 9', 9, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'denotation', '/ˌdiː.noʊˈteɪ.ʃən/', 'n.', 'Nghĩa đen, định nghĩa trực tiếp', 'While the literal denotation of the word ''sanctuary'' signifies a sacred place or protective shelter, its poetic connotation frequently evokes spiritual solace and redemption.', 'Lesson 9', 9, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'denouement', '/deɪˈnuː.mɑː/', 'n.', 'Hồi kết, đoạn kết mở nút (cốt truyện)', 'In the gripping denouement of the courtroom thriller, a long-hidden diary is produced that conclusively proves the accused diplomat had been framed by corporate conspirators.', 'Lesson 9', 9, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'depict', '/dɪˈpɪkt/', 'v.', 'Miêu tả, khắc họa, thể hiện', 'Nineteenth-century realist painters eschewed idealized pastoral mythologies to depict the grueling physical toil endured by agrarian laborers during the autumn wheat harvest.', 'Lesson 9', 9, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deplete', '/dɪˈpliːt/', 'v.', 'Làm cạn kiệt, làm suy giảm', 'Industrial extraction of groundwater has outpaced natural recharge rates, threatening to deplete deep subterranean aquifers essential for continental agriculture.', 'Lesson 9', 9, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deplore', '/dɪˈplɔːr/', 'v.', 'Lên án mạnh mẽ, than trách sâu sắc', 'International human rights monitors issued a joint declaration to deplore the unlawful imprisonment of independent journalists and the suppression of judicial independence.', 'Lesson 9', 9, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deploy', '/dɪˈplɔɪ/', 'v.', 'Triển khai, dàn quân, huy động', 'To contain the virulent bacterial outbreak before it crossed regional borders, health authorities moved quickly to deploy epidemiology units and mobile laboratory field units.', 'Lesson 9', 9, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'depose', '/dɪˈpoʊz/', 'v.', 'Phế truất, cách chức', 'Prompted by years of systematic corruption and economic collapse, a coalition of civilian leaders and military dissidents moved to depose the autocratic head of state.', 'Lesson 9', 9, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deposition', '/ˌdep.əˈzɪʃ.ən/', 'n.', 'Lời khai hữu thệ, sự phế truất, sự lắng đọng', 'During her videotaped deposition, the corporate whistleblower confirmed under oath that pharmaceutical executives had known about severe adverse drug side effects for years.', 'Lesson 9', 9, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'depravity', '/dɪˈpræv.ə.ti/', 'n.', 'Sự suy đồi đạo đức, tính đồi bại', 'Philosophical treatises examining wartime atrocities argue that prolonged exposure to dehumanizing brutality can erode conscience and foster shocking moral depravity.', 'Lesson 9', 9, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deprecate', '/ˈdep.rə.keɪt/', 'v.', 'Phản đối kịch liệt, xem nhẹ', 'Fiscal conservatives in the senate rose to deprecate the omnibus expenditure bill, warning that unfunded municipal subsidies would accelerate national debt accumulation.', 'Lesson 9', 9, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'depreciate', '/dɪˈpriː.ʃi.eɪt/', 'v.', 'Giảm giá trị, sụt giảm giá trị', 'When international commodity markets collapsed, capital flight caused the export-reliant nation''s currency to depreciate precipitously against the reserve currency.', 'Lesson 9', 9, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'depredation', '/ˌdep.rəˈdeɪ.ʃən/', 'n.', 'Sự cướp bóc, sự tàn phá hủy hoại', 'Centuries of relentless coastal depredation by North African corsairs forced Mediterranean islanders to abandon unprotected fishing ports for fortified hill retreats.', 'Lesson 9', 9, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deranged', '/dɪˈreɪndʒd/', 'adj.', 'Loạn trí, hoảng loạn, điên loạn', 'Forensic psychiatric examiners concluded that the accused was deeply deranged at the moment of the assault, suffering from acute psychotic breaks that impaired reality testing.', 'Lesson 9', 9, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'derelict', '/ˈder.ə.lɪkt/', 'adj.', 'Bị bỏ hoang, tiêu điều, lơ là trách nhiệm', 'Following decades of deindustrialization, the derelict iron foundry stood decaying along the riverbank, its shattered skylights framing rust-encrusted machinery.', 'Lesson 9', 9, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deride', '/dɪˈraɪd/', 'v.', 'Chế nhạo, giễu cợt, khinh bỉ', 'Conservative medical authorities initially chose to deride Ignaz Semmelweis''s handwashing mandates, mocking the revolutionary idea that physician hygiene prevented fatal puerperal fever.', 'Lesson 9', 9, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'derivative', '/dɪˈrɪv.ə.tɪv/', 'adj.', 'Bắt chước, không có tính nguyên bản', 'Art critics conceded that the painter possessed impeccable brush technique, yet they ultimately judged the exhibition to be derivative of early twentieth-century Cubist masterpieces.', 'Lesson 9', 9, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dermatologist', '/ˌdɜːr.məˈtɑː.lə.dʒɪst/', 'n.', 'Bác sĩ da liễu, chuyên gia da liễu', 'Detecting asymmetrical borders and varied pigmentation during a routine dermoscopic examination, the attentive dermatologist performed an immediate excision to evaluate the suspect lesion.', 'Lesson 9', 9, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'derogatory', '/dɪˈrɑːɡətɔːri/', 'adj.', 'Mang tính xúc phạm, làm giảm uy tín hoặc coi thường', 'The editorial drew widespread condemnation for its derogatory characterization of immigrant workers, which critics argued stoked xenophobia rather than contributing to constructive policy debates.', 'Lesson 9', 9, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'descant', '/dɪsˈkænt/', 'v.', 'Bàn luận hoặc thuyết giảng chi tiết về một chủ đề', 'During his evening lectures, the venerable classicist would often descant at length upon the rhetorical subtleties of Cicero''s orations.', 'Lesson 9', 9, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'descry', '/dɪˈskraɪ/', 'v.', 'Nhìn thấy hoặc phát hiện ra từ xa hoặc lờ mờ', 'Scanning the storm-tossed horizon through his spyglass, the navigator managed to descry the faint, flickering beacon of the coastal lighthouse.', 'Lesson 9', 9, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'desecrate', '/ˈdesɪkreɪt/', 'v.', 'Mạo phạm, bôi nhọ hoặc làm ô uế nơi thiêng liêng', 'Vandals who breached the cathedral compound sought to desecrate the sanctuary by toppling centuries-old marble altars and defacing religious iconography.', 'Lesson 9', 9, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'desiccate', '/ˈdesɪkeɪt/', 'v.', 'Làm khô cạn, rút hết độ ẩm hoặc sấy khô hoàn toàn', 'Prolonged meteorological drought threatened to desiccate the fertile wetland ecosystem, leaving migratory waterfowl without vital foraging grounds.', 'Lesson 9', 9, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'desolate', '/ˈdesələt/', 'adj.', 'Hoang vắng, tiêu điều, cô độc tuyệt vọng', 'Following the abrupt closure of the iron foundry, the boomtown was reduced to a desolate expanse of boarded storefronts and windswept avenues.', 'Lesson 9', 9, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'despise', '/dɪˈspaɪz/', 'v.', 'Khinh rẻ, coi thường hoặc ghét cay ghét đắng', 'Though the sycophantic courtiers flattered the monarch to his face, they secretly despised his petty vindictiveness and capricious cruelty.', 'Lesson 9', 9, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'despoil', '/dɪˈspɔɪl/', 'v.', 'Cướp đoạt, tước đoạt hoặc bóc lột của cải', 'Unregulated strip-mining operations threatened to despoil the pristine river basin, stripping indigenous communities of both their ancestral homeland and ecological sustenance.', 'Lesson 9', 9, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'despondent', '/dɪˈspɑːndənt/', 'adj.', 'Nản lòng, thoái chí hoặc tuyệt vọng', 'After successive laboratory explosions ruined months of synthesis trials, the young chemist grew despondent, questioning the fundamental viability of his hypothesis.', 'Lesson 9', 9, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'despot', '/ˈdespət/', 'n.', 'Kẻ bạo chúa, người cầm quyền độc tài và tàn bạo', 'Refusing to tolerate any semblance of dissent, the military despot dismantled the independent judiciary and shuttered opposition printing presses.', 'Lesson 9', 9, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'destitute', '/ˈdestɪtuːt/', 'adj.', 'Cực kì nghèo khổ, bần cùng, thiếu thốn', 'The catastrophic deflation of the agrarian economy left thousands of tenant sharecroppers entirely destitute, dependent on meager municipal rations.', 'Lesson 9', 9, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'desultory', '/ˈdesəltɔːri/', 'adj.', 'Rời rạc, không có hệ thống hoặc mục đích rõ ràng', 'The congressional hearing produced little actionable insight because the committee engaged in desultory questioning rather than pursuing a cohesive investigative line.', 'Lesson 9', 9, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'detached', '/dɪˈtætʃt/', 'adj.', 'Khách quan, vô tư, không bị cảm xúc chi phối', 'A supreme court justice is expected to maintain a detached demeanor, weighing contentious constitutional disputes purely through statutory analysis rather than partisan sentiment.', 'Lesson 9', 9, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'determination', '/dɪˌtɜːrmɪˈneɪʃn/', 'n.', 'Sự quyết tâm kiên định hoặc sự xác định chính xác', 'The paleontologist''s relentless determination to excavate the fossilized strata eventually yielded an intact specimen that revolutionized avian evolutionary taxonomy.', 'Lesson 9', 9, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deterrent', '/dɪˈtɜːrənt/', 'n.', 'Vật ngăn chặn, biện pháp răn đe', 'Geopolitical analysts maintain that a well-enforced regime of multilateral economic sanctions serves as an indispensable deterrent against cross-border aggression.', 'Lesson 9', 9, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'detonation', '/ˌdetəˈneɪʃn/', 'n.', 'Sự phát nổ, sự kích nổ', 'Seismographic stations across the continent recorded the precise tremor generated by the underground detonation of the experimental ordinance.', 'Lesson 9', 9, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'detraction', '/dɪˈtrækʃn/', 'n.', 'Sự gièm pha, bôi nhọ hoặc làm giảm uy tín', 'The pioneering astronomer endured years of malicious detraction from entrenched academic peers before orbital photographs indisputably confirmed her stellar models.', 'Lesson 9', 9, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'detrimental', '/ˌdetrɪˈmentl/', 'adj.', 'Có hại, gây tổn hại hoặc bất lợi', 'Agronomists warned that the excessive application of synthetic nitrogen fertilizers exerts detrimental effects on subterranean microbiomes and local aquifer purity.', 'Lesson 9', 9, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deviate', '/ˈdiːvieɪt/', 'v.', 'Chệch hướng, làm khác đi so với lộ trình hoặc tiêu chuẩn', 'When thermal fluctuations caused the automated spacecraft to deviate slightly from its orbital corridor, onboard guidance thrusters fired immediate correctional pulses.', 'Lesson 9', 9, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'devious', '/ˈdiːviəs/', 'adj.', 'Láu cá, quỷ quyệt, quanh co không trung thực', 'The minister utilized devious backroom stratagems and confidential leakages to undermine his cabinet rivals without exposing himself to public scrutiny.', 'Lesson 9', 9, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'devise', '/dɪˈvaɪz/', 'v.', 'Phát minh, sáng chế, đặt ra kế hoạch', 'Ecological engineers must devise novel desalination architectures that reduce caloric energy consumption while protecting fragile littoral marine habitats.', 'Lesson 9', 9, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'devoid', '/dɪˈvɔɪd/', 'adj.', 'Hoàn toàn không có, trống rỗng', 'The author''s stark prose style was purposefully devoid of sentimental embellishment, lending the harrowing war chronicle an air of unvarnished documentary realism.', 'Lesson 9', 9, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'devotee', '/ˌdevəˈtiː/', 'n.', 'Người say mê cuồng nhiệt, tín đồ trung thành', 'As an impassioned devotee of Renaissance polyphony, the maestro spent decades scouring monastic archives for forgotten choral manuscripts.', 'Lesson 9', 9, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'devout', '/dɪˈvaʊt/', 'adj.', 'Sùng đạo, thành tâm mộ đạo', 'The pilgrim community adhered to devout traditions of predawn meditation and communal fasting, seeking spiritual transcendence away from modern distractions.', 'Lesson 9', 9, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dexterous', '/ˈdekstrəs/', 'adj.', 'Khéo léo, thuần thục, tinh xảo', 'The watchmaker''s dexterous manipulation of microscopic gears and escapements required decades of meticulous manual apprenticeship.', 'Lesson 9', 9, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diabolical', '/ˌdaɪəˈbɑːlɪkl/', 'adj.', 'Tàn ác như quỷ dữ, thâm hiểm độc ác', 'The prosecutor unmasked the syndicate''s diabolical scheme to adulterate neonatal pharmaceuticals with inert solvents to inflate corporate profit margins.', 'Lesson 9', 9, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diagnosis', '/ˌdaɪəɡˈnoʊsɪs/', 'n.', 'Sự chẩn đoán bệnh trạng hoặc căn nguyên vấn đề', 'Molecular pathology enabled clinicians to render an definitive genetic diagnosis long before clinical symptoms of the neuromuscular disease manifested.', 'Lesson 9', 9, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discomfit', '/dɪsˈkʌmfɪt/', 'v.', 'Làm bối rối, làm lúng túng, khiến bồn chồn', 'The investigative reporter''s pointed questions regarding undisclosed offshore accounts visibly discomfited the corporate spokesperson during the press conference.', 'Lesson 9', 9, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discomposure', '/ˌdɪskəmˈpoʊʒər/', 'n.', 'Sự mất bình tĩnh, sự bối rối hoặc mất tự chủ', 'Despite his aristocratic poise, the ambassador could not conceal his discomposure when confronted with intercepted cables exposing his covert alliances.', 'Lesson 9', 9, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disconcert', '/ˌdɪskənˈsɜːrt/', 'v.', 'Làm bối rối, làm lúng túng hoặc làm mất tự nhiên', 'The sudden and unprovoked resignation of the lead defense attorney threatened to disconcert the entire legal defense team on the eve of the trial.', 'Lesson 9', 9, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disconsolate', '/dɪsˈkɑːnsələt/', 'adj.', 'U sầu, đau buồn khôn xiết, không thể an ủi', 'In the wake of the devastating shipwreck, disconsolate families congregated upon the stormy bluffs, staring hopelessly into the unforgiving surf.', 'Lesson 9', 9, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discord', '/ˈdɪskɔːrd/', 'n.', 'Sự bất hòa, sự xung đột hoặc âm thanh nghịch tai', 'Simmering sectarian discord between rival factions paralyzed the transitional government and stalled constitutional negotiations.', 'Lesson 9', 9, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discordant', '/dɪsˈkɔːrdənt/', 'adj.', 'Bất hòa, trái ngược hoặc chói tai, không hòa hợp', 'The speaker''s inflammatory rhetoric introduced a discordant element into what had otherwise been a harmonious diplomatic symposium.', 'Lesson 9', 9, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discount', '/dɪsˈkaʊnt/', 'v.', 'Xem nhẹ, không coi trọng hoặc chiết khấu, giảm giá', 'Climatologists warned national policymakers not to discount subtle shifts in ocean currents, which could trigger catastrophic regional weather disruptions.', 'Lesson 9', 9, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discourse', '/ˈdɪskɔːrs/', 'n.', 'Bài diễn thuyết, đàm thoại hoặc diễn ngôn học thuật', 'Enlightenment philosophers maintained that civil discourse governed by rational inquiry is the indispensable bedrock of a thriving democratic republic.', 'Lesson 9', 9, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discredit', '/dɪsˈkredɪt/', 'v.', 'Làm mất uy tín, làm giảm độ tin cậy hoặc bác bỏ', 'Subsequent laboratory replications failed to substantiate the controversial findings, effectively discrediting the physicist''s revolutionary claims.', 'Lesson 9', 9, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discrepancy', '/dɪˈskrepənsi/', 'n.', 'Sự khác biệt, sự không nhất quán giữa các con số hoặc dữ kiện', 'Forensic auditors identified a glaring discrepancy between the corporate ledger and the taxable revenue declared to the federal treasury.', 'Lesson 9', 9, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discrete', '/dɪˈskriːt/', 'adj.', 'Riêng biệt, rời rạc, độc lập với nhau', 'Cognitive neuroscientists demonstrated that episodic memory and motor procedural skill are mediated by discrete neural circuits within the cerebral cortex.', 'Lesson 9', 9, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discretion', '/dɪˈskreʃn/', 'n.', 'Quyền tự do quyết định hoặc sự thận trọng kín đáo', 'The statutory statute confers broad administrative discretion upon the environmental commissioner to adjust emission caps during ecological emergencies.', 'Lesson 9', 9, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discriminating', '/dɪˈskrɪmɪneɪtɪŋ/', 'adj.', 'Có óc phán đoán tốt, biết phân biệt tinh tế', 'The gallery curator possessed a discriminating eye for composition, instantly distinguishing authentic Renaissance canvasses from late romantic imitations.', 'Lesson 9', 9, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discursive', '/dɪˈskɜːrsɪv/', 'adj.', 'Lan man, không tập trung, dông dài', 'Though packed with erudite allusions, the author''s discursive treatise wandered aimlessly across disparate theological debates without ever answering its core thesis.', 'Lesson 9', 9, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disdain', '/dɪsˈdeɪn/', 'n.', 'Sự khinh miệt, thái độ coi thường', 'The patrician aristocracy viewed the rising merchant class with open disdain, scoffing at their commercial fortunes as vulgar and unrefined.', 'Lesson 9', 9, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disembark', '/ˌdɪsɪmˈbɑːrk/', 'v.', 'Xuống tàu, máy bay hoặc các phương tiện vận tải', 'Upon anchoring in the sheltered harbor, the weary expeditionary crew prepared to disembark and establish an inland encampment.', 'Lesson 9', 9, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disenfranchise', '/ˌdɪsɪnˈfræntʃaɪz/', 'v.', 'Tước quyền công dân, đặc biệt là quyền bầu cử', 'Arbitrary residency requirements and restrictive voter identification laws were historically leveraged to disenfranchise vulnerable minority populations.', 'Lesson 9', 9, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disengage', '/ˌdɪsɪnˈɡeɪdʒ/', 'v.', 'Tháo rời, tách ra hoặc rút lui', 'Recognizing that the regional insurgency was drawing imperial forces into an unwinnable quagmire, the field commander chose to disengage his battalions and fortify the frontier.', 'Lesson 9', 9, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disfigure', '/dɪsˈfɪɡjər/', 'v.', 'Làm biến dạng, làm mất đi vẻ thẩm mỹ vốn có', 'Centuries of industrial air pollution and atmospheric acid deposition have begun to corrode and disfigure the intricate limestone relief sculptures of the cathedral facade.', 'Lesson 9', 9, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disgorge', '/dɪsˈɡɔːrdʒ/', 'v.', 'Nôn ra, tuôn ra hoặc xả ra lượng lớn', 'When the subterranean lava tube finally fractured under tectonic pressure, the volcanic caldera began to disgorge colossal torrents of basaltic magma.', 'Lesson 9', 9, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disgruntle', '/dɪsˈɡrʌntl/', 'v.', 'Làm cho bực bội, bất mãn hoặc cau có', 'The administration''s arbitrary suspension of customary health benefits did much to disgruntle the factory workforce and trigger wildcat walkouts.', 'Lesson 9', 9, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dishearten', '/dɪsˈhɑːrtn/', 'v.', 'Làm nản lòng, làm mất đi niềm tin và nhuệ khí', 'The persistent denial of federal grant renewals threatened to dishearten the young epidemiological researchers studying antimicrobial resistance.', 'Lesson 9', 9, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disheveled', '/dɪˈʃevld/', 'adj.', 'Luộm thuộm, xộc xệch, rối bời (đầu tóc, quần áo)', 'Emerging from weeks of solitary confinement in the damp dungeon, the prisoner stood before the magistrates with gaunt cheeks and disheveled garments.', 'Lesson 9', 9, 100),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disinclination', '/ˌdɪsˌɪnklɪˈneɪʃn/', 'n.', 'Sự miễn cưỡng, sự ngần ngại, sự thiếu hào hứng', 'Despite lucrative commercial offers from private industry, the veteran astronomer demonstrated a clear disinclination to abandon her university laboratory and academic research.', 'Lesson 10', 10, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disingenuous', '/ˌdɪsɪnˈdʒɛnjuəs/', 'adj.', 'Không chân thật, xảo trá, giả vờ ngây ngô', 'Editorial writers condemned the diplomat''s remarks as disingenuous, arguing that he knowingly feigned ignorance of the border skirmishes to avert international sanctions.', 'Lesson 10', 10, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disinter', '/ˌdɪsɪnˈtɜːr/', 'v.', 'Khai quật, quật mộ, đưa ra ánh sáng', 'Authorized by a court order, forensic pathologists arrived at dawn to disinter the victim''s remains in hopes of uncovering toxicological evidence overlooked decades earlier.', 'Lesson 10', 10, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disinterested', '/dɪsˈɪntrəstɪd/', 'adj.', 'Công tâm, vô tư, không vụ lợi', 'To guarantee an equitable arbitration, the treaty required disputes to be mediated by a disinterested tribunal with no stake in regional commerce.', 'Lesson 10', 10, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disjointed', '/dɪsˈdʒɔɪntɪd/', 'adj.', 'Rời rạc, đứt đoạn, thiếu mạch lạc', 'Suffering from high fever and exhaustion, the explorer delivered a disjointed narrative whose abrupt chronological jumps left the rescue crew perplexed.', 'Lesson 10', 10, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dislodge', '/dɪsˈlɑːdʒ/', 'v.', 'Đánh bật, trục xuất, làm bật ra khỏi vị trí', 'Torrents of glacial meltwater surged through the narrow ravine, dislodging massive granite boulders that had rested undisturbed along the canyon floor for centuries.', 'Lesson 10', 10, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dismantle', '/dɪsˈmæntl/', 'v.', 'Tháo dỡ, triệt hạ cấu trúc hoặc hệ thống', 'Following the historic nonproliferation treaty, international atomic inspectors oversaw specialized teams tasked with safely dismantling the decommissioned plutonium enrichment plant.', 'Lesson 10', 10, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dismay', '/dɪsˈmeɪ/', 'n.', 'Sự mất tinh thần, nỗi thất vọng pha lẫn âu lo', 'To the profound dismay of environmental scientists, the regulatory commission voted to weaken emissions caps despite overwhelming empirical data indicating escalating global temperatures.', 'Lesson 10', 10, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dismember', '/dɪsˈmɛmbər/', 'v.', 'Phân chia lãnh thổ, cắt xẻ tứ chi', 'The victorious coalition convened at the peace congress with the explicit intention to dismember the defeated empire into several autonomous border provinces.', 'Lesson 10', 10, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dismiss', '/dɪsˈmɪs/', 'v.', 'Gạt bỏ, bác bỏ, coi nhẹ', 'Establishment astronomers originally dismissed the amateur stargazer''s planetary observations as instrument error until subsequent satellite imagery confirmed the presence of a new asteroid belt.', 'Lesson 10', 10, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disparage', '/dɪˈspærɪdʒ/', 'v.', 'Gièm pha, miệt thị, hạ thấp giá trị', 'Traditionalist art critics routinely disparaged modern abstract painting, claiming that nonrepresentational canvases required neither technical mastery nor aesthetic discipline.', 'Lesson 10', 10, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disparate', '/ˈdɪspərət/', 'adj.', 'Khác biệt căn bản, hoàn toàn dị biệt', 'The interdisciplinary research seminar brought together scholars from disparate disciplines—including computational linguistics, behavioral economics, and cultural anthropology—to investigate human decision-making.', 'Lesson 10', 10, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disparity', '/dɪˈspærɪti/', 'n.', 'Sự chênh lệch lớn, sự bất bình đẳng', 'A comprehensive public health audit revealed a stark disparity in access to specialized pediatric care between prosperous metropolitan centers and impoverished rural counties.', 'Lesson 10', 10, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dispassionate', '/dɪsˈpæʃənət/', 'adj.', 'Khách quan, điềm tĩnh, không thiên vị', 'A reliable constitutional jurist must adopt a dispassionate posture, interpreting statutory texts through legal precedent rather than personal political convictions.', 'Lesson 10', 10, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dispatch', '/dɪˈspætʃ/', 'v.', 'Phái đi, gửi đi nhanh chóng', 'Upon receiving intelligence of an unauthorized naval intrusion, the admiralty immediately dispatched three reconnaissance frigates to patrol the contested territorial waters.', 'Lesson 10', 10, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dispel', '/dɪˈspɛl/', 'v.', 'Xua tan, dẹp bỏ hoài nghi hoặc nỗi sợ', 'Rigorous longitudinal data published in the medical journal helped dispel widespread public misconceptions regarding the safety and efficacy of mRNA vaccines.', 'Lesson 10', 10, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disperse', '/dɪˈspɜːrs/', 'v.', 'Phân tán, giải tán, rải rác khắp nơi', 'Once the torrential rain subsided and the autumn winds gathered strength, the seeds of the milkweed pod were dispersed across the prairie landscape.', 'Lesson 10', 10, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dispirited', '/dɪˈspɪrɪtɪd/', 'adj.', 'Chán nản, nản lòng, nhụt chí', 'Plagued by unending supply shortages and brutal winter storms, the dispirited garrison lost the will to resist the encroaching besiegers.', 'Lesson 10', 10, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disputatious', '/ˌdɪspjuːˈteɪʃəs/', 'adj.', 'Hiếu biện, thích tranh luận, hay cãi cọ', 'Known for his disputatious temperament, the young parliamentarian turned every routine budgetary discussion into a ferocious philosophical quarrel.', 'Lesson 10', 10, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disquiet', '/dɪsˈkwaɪət/', 'n.', 'Sự bất an, nỗi âu lo, cảm giác bồn chồn', 'Unconfirmed reports of troop movements along the northern frontier sowed deep disquiet among urban shopkeepers, prompting many to hoard essential foodstuffs.', 'Lesson 10', 10, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissection', '/dɪˈsɛkʃn/', 'n.', 'Sự mổ xẻ, sự phân tích chi tiết', 'The literary theorist’s rigorous dissection of the author''s early poetry revealed hidden autobiographical allegories beneath seemingly pastoral motifs.', 'Lesson 10', 10, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissemble', '/dɪˈsɛmbl/', 'v.', 'Che giấu, ngụy tạo, giấu giếm cảm xúc thật', 'Unable to dissemble her profound indignation any longer, the whistleblower stood before the congressional committee and exposed the corporation''s toxic dumping practices.', 'Lesson 10', 10, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disseminate', '/dɪˈsɛmɪneɪt/', 'v.', 'Phổ biến, lan truyền, truyền bá rộng rãi', 'During the early decades of the printing revolution, underground broadsides helped disseminate radical democratic ideals to literate working-class citizens.', 'Lesson 10', 10, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissent', '/dɪˈsɛnt/', 'v.', 'Bất đồng quan điểm, phản đối ý kiến chính thống', 'In her sharply worded opinion, Justice Harlan dissented from the ruling, arguing passionately that racial segregation statutes violated the core equal protection guarantees of the Constitution.', 'Lesson 10', 10, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissertation', '/ˌdɪsərˈteɪʃn/', 'n.', 'Luận án, luận văn nghiên cứu chuyên sâu', 'To complete his doctoral dissertation in maritime economic history, Arthur spent years in Lisbon transcribing sixteenth-century spice trade ledgers.', 'Lesson 10', 10, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissident', '/ˈdɪsɪdənt/', 'n.', 'Người bất đồng chính kiến, người phản kháng', 'Despite continuous surveillance and house arrest, the prominent dissident published clandestine tracts denouncing the junta''s suppression of basic civil liberties.', 'Lesson 10', 10, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissimulate', '/dɪˈsɪmjuleɪt/', 'v.', 'Che đậy, ngụy trang suy nghĩ hoặc cảm xúc', 'Skilled in the treacherous etiquette of the royal court, the ambitious duke learned to dissimulate his contempt for the prime minister beneath lavish praise.', 'Lesson 10', 10, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissipate', '/ˈdɪsɪpeɪt/', 'v.', 'Xua tan, tiêu tan, phung phí năng lượng hoặc tài nguyên', 'As midday heat warmed the coastal valley, the dense blanket of maritime fog began to dissipate, uncovering the sparkling waters of the bay.', 'Lesson 10', 10, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissolute', '/ˈdɪsəluːt/', 'adj.', 'Phóng đãng, trụy lạc, trác táng', 'Historical chroniclers depicted the young monarch''s court as notoriously dissolute, dominated by lavish midnight revels and reckless financial mismanagement.', 'Lesson 10', 10, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissolution', '/ˌdɪsəˈluːʃn/', 'n.', 'Sự giải tán, sự giải thể, sự tan rã', 'The sudden dissolution of the governing parliamentary coalition precipitated an early national election amidst severe financial turmoil.', 'Lesson 10', 10, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissonance', '/ˈdɪsənəns/', 'n.', 'Sự bất hòa, sự nghịch tai, mâu thuẫn nhận thức', 'The modern composer juxtaposed traditional orchestral melodies with abrupt chromatic dissonance to mirror the disorienting pace of industrialized urban life.', 'Lesson 10', 10, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissuade', '/dɪˈsweɪd/', 'v.', 'Khuyên can, can ngăn', 'Recognizing the peril of traversing the alpine pass during a sudden blizzard, the veteran sherpa managed to dissuade the expedition from proceeding further.', 'Lesson 10', 10, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distant', '/ˈdɪstənt/', 'adj.', 'Xa cách, lạnh nhạt, xa xôi', 'Deeply shaken by the courtroom revelations, the defendant withdrew into himself, offering only distant and monosyllabic answers to his defense attorney''s inquiries.', 'Lesson 10', 10, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distend', '/dɪˈstɛnd/', 'v.', 'Làm căng phồng, sưng phồng, giãn nở', 'Emergency veterinarians noted that the ingested foreign obstruction had caused the canine''s abdomen to distend dangerously, requiring immediate surgical intervention.', 'Lesson 10', 10, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distill', '/dɪˈstɪl/', 'v.', 'Chưng cất, đúc kết tinh túy', 'In her seminal work on jurisprudence, the legal philosopher managed to distill thousands of pages of convoluted statutory case law into three fundamental moral principles.', 'Lesson 10', 10, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distinction', '/dɪˈstɪŋkʃn/', 'n.', 'Sự phân biệt, nét đặc trưng, sự ưu tú', 'The epistemologist emphasized a crucial distinction between empirical claims verified through sensory experience and purely deductive truths arrived at by logical deduction.', 'Lesson 10', 10, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distort', '/dɪˈstɔːrt/', 'v.', 'Xuyên tạc, bóp méo, làm biến dạng', 'Critics accused the sensationalist documentary of deliberately distorting the anthropological record to portray a peaceful indigenous community as inherently warlike.', 'Lesson 10', 10, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distraught', '/dɪˈstrɔːt/', 'adj.', 'Quẫn trí, hoảng loạn, đau khổ tột cùng', 'Distraught by news of the catastrophic shipwreck off the cape, desperate families huddled together on the windswept pier praying for word of survivors.', 'Lesson 10', 10, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diurnal', '/daɪˈɜːrnl/', 'adj.', 'Hoạt động ban ngày, thuộc về ban ngày', 'While many desert rodents emerge only at night to escape lethal thermal stress, diurnal species like the antelope ground squirrel possess specialized physiological adaptations for foraging under the midday sun.', 'Lesson 10', 10, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diva', '/ˈdiːvə/', 'n.', 'Nữ danh ca opera, người tự phụ kiêu kỳ', 'Famed both for her peerless vocal agility and her imperious backstage conduct, the operatic diva commanded total deference from conductors and stagehands alike.', 'Lesson 10', 10, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diverge', '/daɪˈvɜːrdʒ/', 'v.', 'Phân kỳ, rẽ ra các hướng khác nhau', 'Although both evolutionary lineages originated from a common proto-primate ancestor, their anatomical adaptations began to diverge sharply following the formation of the Rift Valley.', 'Lesson 10', 10, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'divergent', '/daɪˈvɜːrdʒənt/', 'adj.', 'Khác biệt, bất đồng, phân kỳ', 'The macroeconomic panel presented strikingly divergent forecasts regarding post-war recovery, with one faction anticipating rapid industrial rebound and the other predicting entrenched stagflation.', 'Lesson 10', 10, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diverse', '/daɪˈvɜːrs/', 'adj.', 'Đa dạng, muôn vẻ, phong phú', 'The ancient imperial capital drew merchant caravans from diverse geographic regions, blending Central Asian textile craftsmanship with Mediterranean metallurgical techniques.', 'Lesson 10', 10, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diversion', '/daɪˈvɜːrʒn/', 'n.', 'Sự làm chệch hướng, hoạt động giải trí tiêu khiển', 'The general ordered an infantry regiment to feign a river crossing as a tactical diversion, thereby drawing enemy reserves away from the primary assault corridor.', 'Lesson 10', 10, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diversity', '/daɪˈvɜːrsɪti/', 'n.', 'Tính đa dạng, sự phong phú', 'Ecological studies confirm that high levels of botanical diversity significantly enhance the resilience of temperate grassland communities against severe climatic disruptions.', 'Lesson 10', 10, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'divest', '/daɪˈvɛst/', 'v.', 'Tước bỏ, thoái vốn, tước đoạt quyền lợi', 'Under mounting ethical pressure from student organizations, the university board of trustees voted unanimously to divest its multi-billion-dollar endowment from overseas mining conglomerates.', 'Lesson 10', 10, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'divine', '/dɪˈvaɪn/', 'v.', 'Đoán biết bằng trực giác, tiên đoán', 'Drawing upon decades of maritime navigation, the seasoned captain seemed able to divine shifting ocean currents simply by observing subtle variations in wave crests and foam patterns.', 'Lesson 10', 10, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'divulge', '/daɪˈvʌldʒ/', 'v.', 'Tiết lộ, để lộ thông tin bí mật', 'Bound by professional oaths and rigorous state secrecy acts, the cipher clerk refused to divulge the cryptographic keys used to decipher intercepted diplomatic cables.', 'Lesson 10', 10, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'docile', '/ˈdoʊsaɪl/', 'adj.', 'Dễ bảo, ngoan ngoãn, thuần phục', 'Over generations of selective breeding, pastoralists converted the aggressive wild aurochs into a docile domestic breed capable of plowing rocky terraced slopes.', 'Lesson 10', 10, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doctrinaire', '/ˌdɑːktrɪˈnɛr/', 'adj.', 'Giáo điều, cứng nhắc, bám chấp lý thuyết', 'The treasury secretary’s doctrinaire commitment to unregulated free-market dogma blindfolded him to the systemic liquidity crises crippling rural credit cooperatives.', 'Lesson 10', 10, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doctrine', '/ˈdɒktrɪn/', 'n.', 'Học thuyết, giáo lý', 'The Monroe Doctrine asserted that any further European colonization in the Western Hemisphere would be viewed as an act of hostility toward the United States.', 'Lesson 10', 10, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'document', '/ˈdɒkjument/', 'v.', 'Ghi chép tài liệu, thu thập bằng chứng', 'Anthropologists spent decades in the Amazon basin to meticulously document the endangered oral traditions and botanical remedies of indigenous healers.', 'Lesson 10', 10, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doff', '/dɒf/', 'v.', 'Cởi bỏ mũ, ngả mũ chào', 'As the funeral cortege passed through the village square, the solemn townsfolk stepped forward to doff their hats in quiet reverence.', 'Lesson 10', 10, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dogged', '/ˈdɒɡɪd/', 'adj.', 'Kiên cường, bền bỉ, gan góc', 'Through years of archival dead ends and bureaucratic obstruction, the investigative journalist pursued the corruption scandal with dogged determination.', 'Lesson 10', 10, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doggerel', '/ˈdɒɡərəl/', 'n.', 'Thơ vần vè vụng về, thơ dở', 'Dismissing the political pamphlet as mere doggerel, the literary critic argued that its clumsy couplets and irregular meter lacked artistic merit.', 'Lesson 10', 10, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dogmatic', '/dɒɡˈmætɪk/', 'adj.', 'Giáo điều, độc đoán', 'Rather than encouraging open empirical debate, the committee chairman adopted a dogmatic stance, summarily rejecting any hypothesis that challenged conventional wisdom.', 'Lesson 10', 10, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doldrums', '/ˈdɒldrəmz/', 'n.', 'Tình trạng đình trệ, cảnh ảm đạm', 'Targeted public investments in renewable infrastructure finally helped lift the regional manufacturing sector out of its prolonged economic doldrums.', 'Lesson 10', 10, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doleful', '/ˈdəʊlfl/', 'adj.', 'U sầu, buồn thảm, ai oán', 'The solitary cellist played a doleful elegy whose melancholic cadences echoed mournfully through the cavernous sanctuary.', 'Lesson 10', 10, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dolt', '/dəʊlt/', 'n.', 'Kẻ khờ dại, người ngu ngốc', 'Though political rivals unfairly dismissed him as a bumbling dolt, the premier quietly outmaneuvered his opponents through shrewd parliamentary tactics.', 'Lesson 10', 10, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'domicile', '/ˈdɒmɪsaɪl/', 'n.', 'Nơi cư trú, nơi thường trú', 'To claim statutory tax exemption, the expatriate was required to furnish legal records establishing that her permanent domicile remained overseas.', 'Lesson 10', 10, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'domineer', '/ˌdɒmɪˈnɪər/', 'v.', 'Áp chế, hống hách, lấn át', 'The imperious party leader sought to domineer over junior legislators, demanding absolute allegiance on every contentious policy vote.', 'Lesson 10', 10, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'don', '/dɒn/', 'v.', 'Mặc vào, khoác lên', 'Before venturing onto the lunar surface, astronauts were required to don pressurized suits engineered to withstand extreme thermal fluctuations.', 'Lesson 10', 10, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doodle', '/ˈduːdl/', 'v.', 'Vẽ nguệch ngoạc, vẽ lơ đãng', 'Distracted by the monotonous rhythm of the maritime inquiry, the witness began to doodle intricate nautical charts on the margins of his transcript.', 'Lesson 10', 10, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dormant', '/ˈdɔːmənt/', 'adj.', 'Ngủ yên, tạm thời bất hoạt', 'Seismologists warned that although the stratovolcano had lain dormant for three centuries, magma accumulation indicated a catastrophic eruption was brewing.', 'Lesson 10', 10, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dormer', '/ˈdɔːmə/', 'n.', 'Cửa sổ mái sổ ra', 'Sunlight filtered through the high dormer of the colonial garret, casting sharp geometric shadows across the weathered pine floorboards.', 'Lesson 10', 10, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dossier', '/ˈdɒsieɪ/', 'n.', 'Hồ sơ tài liệu chi tiết', 'Naval counterintelligence compiled an exhaustive dossier chronicling the covert communication channels exploited by foreign espionage rings.', 'Lesson 10', 10, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dote', '/dəʊt/', 'v.', 'Cưng chiều hết mực, yêu quý mù quáng', 'Despite the young aristocrat''s scandalous reputation, his wealthy aunt continued to dote upon him, funding his lavish excursions abroad.', 'Lesson 10', 10, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'douse', '/daʊs/', 'v.', 'Dội nước làm ướt sũng, dập tắt lửa', 'Before evacuating the alpine outpost, rangers had to thoroughly douse the campfire with buckets of snow to prevent a brushfire.', 'Lesson 10', 10, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dowdy', '/ˈdaʊdi/', 'adj.', 'Luộm thuộm, lỗi mốt, quê mùa', 'Surrounded by aristocrats in embroidered silk robes, the foreign envoy appeared conspicuously dowdy in his plain woolen broadcloth suit.', 'Lesson 10', 10, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'downcast', '/ˈdaʊnkɑːst/', 'adj.', 'Chán nản, thất vọng, ủ rũ', 'When news arrived that the peace negotiations had abruptly collapsed, the weary delegates returned to their quarters in downcast spirits.', 'Lesson 10', 10, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'drab', '/dræb/', 'adj.', 'Xám xịt, nhạt nhẽo, buồn tẻ', 'The post-industrial docklands were dominated by drab concrete warehouses and rusting cranes that stood bleak against the winter sky.', 'Lesson 10', 10, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'draconian', '/drəˈkəʊniən/', 'adj.', 'Hà khắc, cực kỳ nghiêm ngặt', 'Civil rights organizations petitioned the international court against the state''s draconian surveillance statutes, alleging severe violations of privacy.', 'Lesson 10', 10, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dregs', '/dreɡz/', 'n.', 'Cặn bã, phần thừa thãi vô giá trị', 'By the winter of 1777, the besieged garrison had consumed their reserves and were reduced to drinking the foul dregs of stagnant cisterns.', 'Lesson 10', 10, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'drivel', '/ˈdrɪvl/', 'n.', 'Chuyện nhảm nhí, lời nói vô nghĩa', 'The eminent philosopher refused to dignify the sensationalist pamphlet with a rebuttal, dismissing its conspiracy theories as unlettered drivel.', 'Lesson 10', 10, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'droll', '/drəʊl/', 'adj.', 'Khôi hài, hóm hỉnh kỳ quặc', 'With dry wit and deadpan delivery, the satirical columnist offered a droll commentary on the absurdities of metropolitan high society.', 'Lesson 10', 10, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'drone', '/drəʊn/', 'v.', 'Nói giọng đều đều buồn ngủ, kêu vo ve', 'As the parliamentary clerk continued to drone through the dozens of technical amendments, several legislators quietly dozed in their benches.', 'Lesson 10', 10, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dross', '/drɒs/', 'n.', 'Xỉ kim loại, cặn bã vô giá trị', 'The metallurgist carefully skimmed the oxidized dross from the molten silver before pouring the purified metal into casting molds.', 'Lesson 10', 10, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'drudgery', '/ˈdrʌdʒəri/', 'n.', 'Công việc cực nhọc, sự vất vả nhàm chán', 'Prior to the mechanization of agriculture, weeding sprawling cotton fields by hand represented an unremitting drudgery for farm laborers.', 'Lesson 10', 10, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dubious', '/ˈdjuːbiəs/', 'adj.', 'Đáng nghi, mơ hồ, hoài nghi', 'Independent economic analysts remained deeply dubious of the central bank''s inflation forecast, citing volatile global commodity prices.', 'Lesson 10', 10, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ductile', '/ˈdʌktaɪl/', 'adj.', 'Dễ uốn, dễ dát mỏng, dễ uốn nắn', 'Because gold is exceptionally ductile, a single ounce can be drawn into an ultrafine wire extending over fifty miles without fracturing.', 'Lesson 10', 10, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dulcet', '/ˈdʌlsɪt/', 'adj.', 'Êm dịu, ngọt ngào, thánh thót', 'The contralto''s dulcet voice resonated through the stone amphitheater, soothing the tense crowd gathered in the piazza.', 'Lesson 10', 10, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dumbfound', '/dʌmˈfaʊnd/', 'v.', 'Làm chết lặng, làm sửng sốt', 'The astronomer''s revelation that the distant galaxy exhibited impossible orbital mechanics served to dumbfound the astrophysics community.', 'Lesson 10', 10, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dupe', '/djuːp/', 'v.', 'Lừa gạt, đánh lừa', 'By forging official government seals and falsifying deeds, the con artist managed to dupe unsuspecting investors into funding fictitious railroad lines.', 'Lesson 10', 10, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'duplicity', '/djuːˈplɪsəti/', 'n.', 'Tính hai lòng, sự xảo trá', 'The declassified memos exposed the cabinet minister''s duplicity, showing that he secretly courted foreign monopolists while publicly decrying their predatory practices.', 'Lesson 10', 10, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'duration', '/djuˈreɪʃn/', 'n.', 'Thời lượng, khoảng thời gian tồn tại', 'Because the polar night extends for the entire duration of the arctic winter, expedition members must cope with relentless psychological strain.', 'Lesson 10', 10, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'duress', '/djuˈres/', 'n.', 'Sự ép buộc, sự cưỡng ép', 'The tribunal nullified the treaty after uncovering evidence that the sovereign had signed under physical duress and imminent threat of bombardment.', 'Lesson 10', 10, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dutiful', '/ˈdjuːtɪfl/', 'adj.', 'Tận tụy, làm tròn bổn phận, biết vâng lời', 'Throughout four decades of turbulent naval service, the admiral remained a dutiful commander who placed constitutional loyalty above political ambition.', 'Lesson 10', 10, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dwarf', '/dwɔːf/', 'v.', 'Làm lu mờ, thu nhỏ lại khi so sánh', 'The staggering scale of the transcontinental railway project threatened to dwarf all previous civil engineering achievements in the nation''s history.', 'Lesson 10', 10, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dwindle', '/ˈdwɪndl/', 'v.', 'Thu hẹp dần, cạn kiệt dần, suy giảm', 'As annual rainfall plummeted and aquifer levels dropped, municipal water reserves began to dwindle to precarious thresholds.', 'Lesson 10', 10, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dynamic', '/daɪˈnæmɪk/', 'adj.', 'Năng động, luôn biến đổi, năng tiến', 'Ecologists increasingly conceptualize estuaries as dynamic transitional biomes whose species diversity depends on continuous tidal fluctuations.', 'Lesson 10', 10, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'earthy', '/ˈɜːθi/', 'adj.', 'Mộc mạc, chân chất, có mùi đất', 'Chaucer''s Canterbury Tales is celebrated for combining courtly romance with the earthy, ribald humor of fourteenth-century English commoners.', 'Lesson 10', 10, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ebb', '/eb/', 'v.', 'Suy thoái dần, rút dần, tàn lụi', 'As wartime fervor began to ebb across the republic, citizen assemblies voiced escalating dissatisfaction with heavy taxation and trade restrictions.', 'Lesson 10', 10, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ebullient', '/ɪˈbʌliənt/', 'adj.', 'Sôi nổi, hân hoan, tràn đầy năng lượng', 'The orchestra delivered an ebullient rendition of the symphony''s finale, eliciting a roaring standing ovation from the captivated audience.', 'Lesson 10', 10, 93);
